import { ChangeDetectionStrategy, Component, computed, resource, signal } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MatDialogModule } from '@angular/material/dialog';
import { MatExpansionModule } from '@angular/material/expansion';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatProgressBarModule } from '@angular/material/progress-bar';
import { TranslatePipe } from '../../core/i18n/translate.pipe';

/** Entry of public/licenses.json (generated by scripts/licenses.mjs). */
interface LicenseEntry {
  name: string;
  version: string;
  license: string;
  url: string | null;
  usage: string;
  text: string | null;
}

/** Third-party components with their licenses (full text when available). */
@Component({
  selector: 'app-licenses-dialog',
  imports: [MatButtonModule, MatDialogModule, MatExpansionModule, MatFormFieldModule, MatInputModule, MatProgressBarModule, TranslatePipe],
  template: `
    <h2 mat-dialog-title>{{ 'licenses.title' | t }}</h2>
    <mat-dialog-content class="content">
      <p class="about">edimus {{ version }} · Neutralinojs {{ neutralino }}</p>
      <p class="intro">{{ 'licenses.intro' | t }}</p>
      <!-- with the dense theme the floating label is hidden: placeholder instead -->
      <mat-form-field class="filter" appearance="outline" subscriptSizing="dynamic">
        <input matInput [placeholder]="'licenses.filter' | t" [value]="filter()" (input)="filter.set($any($event.target).value)" />
      </mat-form-field>
      @if (entries.isLoading()) {
        <mat-progress-bar mode="indeterminate" />
      } @else if (entries.error()) {
        <p class="error">{{ 'licenses.missing' | t }}</p>
      }
      <mat-accordion displayMode="flat">
        @for (entry of visible(); track entry.name) {
          <mat-expansion-panel [disabled]="!entry.text">
            <mat-expansion-panel-header class="entry">
              <mat-panel-title>
                <span class="entry-name">{{ entry.name }}</span>
                @if (entry.version) {
                  <span class="version">{{ entry.version }}</span>
                }
              </mat-panel-title>
              <mat-panel-description>{{ entry.license }}</mat-panel-description>
            </mat-expansion-panel-header>
            <ng-template matExpansionPanelContent>
              <p class="usage">{{ entry.usage }}@if (entry.url) { — {{ entry.url }}}</p>
              <pre>{{ entry.text }}</pre>
            </ng-template>
          </mat-expansion-panel>
        }
      </mat-accordion>
    </mat-dialog-content>
    <mat-dialog-actions align="end">
      <button mat-button mat-dialog-close>{{ 'common.close' | t }}</button>
    </mat-dialog-actions>
  `,
  styles: `
    .content {
      width: min(860px, 90vw);
      max-height: 75vh;
    }
    .about {
      font: var(--mat-sys-title-small);
      margin-top: 0;
    }
    .intro,
    .usage,
    .version {
      color: var(--mat-sys-on-surface-variant);
      font: var(--mat-sys-body-small);
    }
    /* compact two-line entries: name, then version in small type */
    .entry {
      height: auto !important;
      min-height: 44px;
      padding: 6px 16px;
      font-size: 13px;
    }
    mat-panel-title {
      flex: 0 0 45%;
      flex-direction: column;
      align-items: flex-start;
      justify-content: center;
      gap: 1px;
      min-width: 0;
    }
    .entry-name {
      font-size: 13px;
      line-height: 1.3;
    }
    .version {
      font-size: 11px;
      line-height: 1.2;
      word-break: break-all;
    }
    mat-panel-description {
      font-size: 12px;
      line-height: 1.3;
    }
    .filter {
      width: 100%;
      margin-bottom: 8px;
    }
    pre {
      white-space: pre-wrap;
      font: 12px/1.4 Consolas, monospace;
      max-height: 320px;
      overflow: auto;
      margin: 0;
    }
    .error {
      color: var(--mat-sys-error);
    }
  `,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class LicensesDialogComponent {
  protected readonly version = window.NL_APPVERSION ?? '';
  protected readonly neutralino = window.NL_VERSION ?? '';
  protected readonly filter = signal('');

  protected readonly entries = resource({
    loader: async () => {
      const response = await fetch('licenses.json');
      if (!response.ok) throw new Error(`licenses.json: ${response.status}`);
      return (await response.json()) as LicenseEntry[];
    },
  });

  protected readonly visible = computed(() => {
    const filter = this.filter().trim().toLowerCase();
    const all = this.entries.hasValue() ? this.entries.value() : [];
    return filter ? all.filter((e) => `${e.name} ${e.license}`.toLowerCase().includes(filter)) : all;
  });
}
